<section class="voter-sheet" id="voter-overview" aria-labelledby="voter-overview-title"><div class="voter-sheet-heading"><div><span class="voter-eyebrow">01 / IDENTITY</span><h2 id="voter-overview-title">Personal details</h2></div><?php if($canManage): ?><a class="no-print" href="<?= e($editUrl.'#voter-personal') ?>">Edit</a><?php endif; ?></div><dl class="voter-facts"><?php foreach($personal as $label=>$value): ?><div><dt><?= e($label) ?></dt><dd><?= e($value) ?></dd></div><?php endforeach; ?></dl></section>
